const prime = Array(999).fill(true);
prime[0] = prime[1] = false;
for (let p = 2; p * p <= 998; p++) {
  if (prime[p]) for (let n = p * p; n <= 998; n += p) prime[n] = false;
}
let checked = 0;
const counterexamples = [];
let firstPairFor998 = null;
for (let n = 4; n <= 998; n += 2) {
  checked++;
  let pair = null;
  for (let p = 2; p <= n / 2; p++) {
    if (prime[p] && prime[n - p]) { pair = [p, n - p]; break; }
  }
  if (!pair) counterexamples.push(n);
  if (n === 998) firstPairFor998 = pair;
}
console.log(JSON.stringify({checked, counterexamples, firstPairFor998}));

